class Solution {
    public int lengthOfLIS(int[] nums) {
        int n = nums.length;
        int best = 0;
        for (int mask = 1; mask < (1 << n); mask++) {
            int prev = Integer.MIN_VALUE;
            int len = 0;
            boolean ok = true;
            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) == 0) continue;
                if (nums[i] <= prev) {
                    ok = false;
                    break;
                }
                prev = nums[i];
                len++;
            }
            if (ok) best = Math.max(best, len);
        }
        return best;
    }
}

import java.util.*;

class Solution {
    public int lengthOfLIS(int[] nums) {
        int n = nums.length;
        if (n == 0) return 0;
        int[] dp = new int[n];
        Arrays.fill(dp, 1);

        int best = 1;
        for (int i = 1; i < n; i++) {
            for (int j = 0; j < i; j++) {
                if (nums[j] < nums[i]) dp[i] = Math.max(dp[i], dp[j] + 1);
            }
            best = Math.max(best, dp[i]);
        }
        return best;
    }
}

class Solution {
    public int lengthOfLIS(int[] nums) {
        int n = nums.length;
        int[] tails = new int[n];
        int len = 0;

        for (int x : nums) {
            int left = 0;
            int right = len;
            while (left < right) {
                int mid = left + (right - left) / 2;
                if (tails[mid] < x) left = mid + 1;
                else right = mid;
            }
            tails[left] = x;
            if (left == len) len++;
        }
        return len;
    }
}
